INSERT INTO bridging.questions (id, topic_id, prompt, model_answer, explanation, difficulty, metadata, diagram_path, question_type, answer_tolerance, accepted_answers, case_sensitive, require_simplified_form, require_units, required_unit, accepted_units, marking_notes, syntax_migration_status, syntax_migration_notes, created_at, updated_at) VALUES ('01a00466-c84e-7730-b6f3-4e8b47ddcba5'::uuid, '019f9df7-a2a2-7853-96ff-2c02dc5e1f10'::uuid, 'Simplify 4x - 7(x - 2).', '14 - 3x', '4x - 7(x - 2) = 4x - 7x + 14 = 14 - 3x.', 'Easy', '{"diagram_required":false}'::jsonb, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '2026-08-15T07:50:39.950Z'::timestamptz, '2026-08-15T07:50:39.950Z'::timestamptz) ON CONFLICT (id) DO NOTHING;
INSERT INTO bridging.questions (id, topic_id, prompt, model_answer, explanation, difficulty, metadata, diagram_path, question_type, answer_tolerance, accepted_answers, case_sensitive, require_simplified_form, require_units, required_unit, accepted_units, marking_notes, syntax_migration_status, syntax_migration_notes, created_at, updated_at) VALUES ('01a00466-c868-7374-a22f-9dbc4041ab71'::uuid, '019f9df7-a2a2-7853-96ff-2c02dc5e1f10'::uuid, 'Simplify (18a²b⁴) ÷ (6ab⁻²), leaving your answer with positive indices.', '3ab⁶', '(18a²b⁴)/(6ab⁻²) = 3a^(2-1)b^(4-(-2)) = 3ab⁶.', 'Easy', '{"diagram_required":false}'::jsonb, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '2026-08-15T07:50:39.976Z'::timestamptz, '2026-08-15T07:50:39.976Z'::timestamptz) ON CONFLICT (id) DO NOTHING;
INSERT INTO bridging.questions (id, topic_id, prompt, model_answer, explanation, difficulty, metadata, diagram_path, question_type, answer_tolerance, accepted_answers, case_sensitive, require_simplified_form, require_units, required_unit, accepted_units, marking_notes, syntax_migration_status, syntax_migration_notes, created_at, updated_at) VALUES ('01a00466-c877-7805-8381-a6648746bdb1'::uuid, '019f9df7-a2a2-77cc-bb88-40ce254805a8'::uuid, 'A car travels an average of 0.082 kilometres per litre of fuel. Find its fuel consumption in litres per kilometre, correct to three significant figures.', '12.2 litres per kilometre', 'Litres per kilometre = 1 ÷ 0.082 = 12.195..., which is 12.2 litres per kilometre to three significant figures.', 'Easy', '{"diagram_required":false}'::jsonb, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '2026-08-15T07:50:39.991Z'::timestamptz, '2026-08-15T07:50:39.991Z'::timestamptz) ON CONFLICT (id) DO NOTHING;